sys_script_include.script:
var MaterialFulfillmentDecision = Class.create();
MaterialFulfillmentDecision.prototype = {
    initialize: function () {
        this.STOCK = 'x_2056099_indust_0_inv_stock';
        this.LOC = 'x_2056099_indust_0_inv_loc';
        this.MAT = 'x_2056099_indust_0_mat_master';
        this.LEAD = 'x_2056099_indust_0_transfer_lead_time';
        this.DEC = 'x_2056099_indust_0_fulfill_dec';
        this.ALERT = 'x_2056099_indust_0_inv_alert';
    },

    /**
     * PERSISTING entry point (unchanged behavior).
     * Delegates ALL decision calculation to evaluateReadOnly() (pure, no writes),
     * then persists exactly as before: creates the safety-stock alert when the
     * read-only result directs it, then creates the fulfill_dec decision record.
     *
     * @param {object} params
     *   materialSysId, quantityRequired, warehouseSysId,
     *   customerRequiredDate (optional), customerOrderSysId (optional),
     *   productionOrderSysId (optional)
     * @returns {object} { success, decision_type, decision_sys_id, reason, details }
     */
    evaluate: function (params) {
        var decision = this.evaluateReadOnly(params);
        // Validation / resolution failures pass straight through, unchanged.
        if (!decision || !decision.success) return decision;

        // Persist the safety-stock alert BEFORE the decision record, preserving the
        // original ordering and behavior of the LOCAL_SAFETY_STOCK branch.
        if (decision.alert && decision.alert.stock_sys_id) {
            this._createSafetyStockAlert(
                decision.alert.material,
                decision.alert.warehouse,
                decision.alert.consumed,
                decision.alert.stock_sys_id
            );
        }

        // Persist the decision record and return the same shape as before.
        return this._createDecision(decision.decision_data);
    },

    /**
     * PURE, SIDE-EFFECT-FREE evaluation (BLOCKER 3).
     * Performs the identical validation, warehouse resolution, stock / safety /
     * incoming calculations and decision branching as before, but DOES NOT write
     * to the database: it never calls insert(), update(), deleteRecord(),
     * deleteMultiple(), _createDecision(), or _createSafetyStockAlert(), and runs
     * no Flow/coordination/simulation mutation.
     *
     * When the LOCAL_SAFETY_STOCK branch is selected it returns an `alert`
     * directive describing the alert the persisting caller should create — it does
     * NOT create it here.
     *
     * @param {object} params - same inputs as evaluate()
     * @returns {object} decision object (see _result) or { success:false, error }
     */
    evaluateReadOnly: function (params) {
        if (!params) return this._fail('Parameters required');
        if (!params.materialSysId) return this._fail('materialSysId required');
        if (!params.quantityRequired || params.quantityRequired <= 0)
            return this._fail('quantityRequired must be positive');
        if (!params.warehouseSysId) return this._fail('warehouseSysId required');

        var matId = params.materialSysId;
        var qtyReq = parseFloat(params.quantityRequired);
        var whId = params.warehouseSysId;
        var custDate = params.customerRequiredDate || '';
        var coId = params.customerOrderSysId || '';
        var poId = params.productionOrderSysId || '';

        // Step 1: Validate assigned warehouse
        var router = new x_2056099_indust_0.WarehouseRouter();
        var whResult = router.resolveWarehouse(whId);
        if (!whResult.success) return this._fail('Step 1: ' + whResult.error);
        var assignedWh = whResult.warehouse;

        // Step 2: Validate material
        var matGr = new GlideRecord(this.MAT);
        if (!matGr.get(matId)) return this._fail('Step 2: Material not found');
        var matName = matGr.getValue('name');
        // Procurement visibility: check incoming supply
        var incomingProcurement = this._getIncomingProcurement(matId);
        var supplierSysId = matGr.getValue('preferred_supplier') || '';

        // Steps 3-4: Check assigned warehouse available stock
        // available_quantity already excludes reserved (BR: avail = total - reserved)
        var localStock = this._getStock(matId, whId);
        var availQty = localStock.available;
        var safetyQty = localStock.safety_stock;
        var reservedQty = localStock.reserved;

        // Determine urgency from customer date
        var urgency = this._calcUrgency(custDate);

        // ========================================
        // Step 5: Sufficient available stock?
        // ========================================
        if (availQty >= qtyReq) {
            var reason5 = matName + ': ' + qtyReq + ' units available at ' +
                          assignedWh.location_name + ' (' + availQty +
                          ' available). No other warehouses needed. Safety stock (' +
                          safetyQty + ') preserved.';
            return this._result({
                decision_type: 'LOCAL_AVAILABLE_STOCK',
                material_product: matId,
                required_quantity: qtyReq,
                available_quantity: availQty,
                shortage_quantity: 0,
                assigned_warehouse: whId,
                customer_required_date: custDate,
                customer_order: coId,
                production_order: poId,
                urgency: urgency,
                decision_reason: reason5
            }, {
                feasible: true,
                reserved_quantity: reservedQty,
                recommended_action: 'Fulfill from on-hand available stock at ' + assignedWh.location_name + '.'
            });
        }

        // ========================================
        // Step 6: Calculate shortage
        // ========================================
        var shortage = qtyReq - availQty;

        // ========================================
        // Steps 7-9: Can safety stock cover the shortage?
        // ========================================
        if (availQty + safetyQty >= qtyReq) {
            var safetyConsumed = shortage; // amount taken from safety
            var reason9 = matName + ': ' + qtyReq + ' units needed at ' +
                          assignedWh.location_name + '. Available: ' + availQty +
                          ', shortage: ' + shortage +
                          '. Consuming ' + safetyConsumed +
                          ' from safety stock (' + safetyQty +
                          '). Safety stock NOT permanently reduced — ' +
                          'replenishment/procurement request recommended.';

            return this._result({
                decision_type: 'LOCAL_SAFETY_STOCK',
                material_product: matId,
                required_quantity: qtyReq,
                available_quantity: availQty,
                shortage_quantity: shortage,
                assigned_warehouse: whId,
                safety_stock_consumed: safetyConsumed,
                supplier: supplierSysId,
                customer_required_date: custDate,
                customer_order: coId,
                production_order: poId,
                urgency: urgency,
                decision_reason: reason9
            }, {
                feasible: true,
                reserved_quantity: reservedQty,
                recommended_action: 'Consume safety stock and raise a replenishment request.',
                // Directive only — the persisting caller (evaluate) creates the alert.
                // evaluateReadOnly itself creates NO alert.
                alert: {
                    material: matId,
                    warehouse: whId,
                    consumed: safetyConsumed,
                    stock_sys_id: localStock.stock_sys_id
                }
            });
        }

        // ========================================
        // Step 9b (BLOCKER 2): Available With Incoming Supply
        // On-hand + safety stock cannot cover the requirement, but qualifying
        // incoming procurement (pending/ordered/partially_received, remaining > 0 —
        // the same eligibility rules already applied by _getIncomingProcurement)
        // already covers the shortage. Only classify when an expected delivery date
        // exists AND, if a customer/required date is set, the delivery is on or
        // before it. If there is no expected delivery date, or it misses the
        // deadline, DO NOT claim on-time arrival — fall through to the existing
        // transfer / procurement / unfulfillable paths. Creates no transfer,
        // procurement, alert, or inventory change.
        // ========================================
        var incomingQty = incomingProcurement.total_incoming || 0;
        var earliestIncoming = incomingProcurement.earliest_expected || '';
        if (incomingQty > 0 && (availQty + incomingQty) >= qtyReq && earliestIncoming) {
            var incomingMeetsDeadline = !custDate ||
                new GlideDateTime(earliestIncoming).compareTo(new GlideDateTime(custDate)) <= 0;
            if (incomingMeetsDeadline) {
                var reasonIncoming = matName + ': ' + qtyReq + ' units needed at ' +
                    assignedWh.location_name + '. Available: ' + availQty +
                    ', shortage: ' + shortage + '. Covered by incoming procurement of ' +
                    incomingQty + ' unit(s) expected by ' + earliestIncoming +
                    (custDate ? ' (on or before required date ' + custDate + ')' : '') +
                    '. No new procurement or inter-warehouse transfer required.';
                return this._result({
                    decision_type: 'AVAILABLE_WITH_INCOMING_SUPPLY',
                    material_product: matId,
                    required_quantity: qtyReq,
                    available_quantity: availQty,
                    shortage_quantity: shortage,
                    incoming_quantity: incomingQty,
                    assigned_warehouse: whId,
                    supplier: supplierSysId,
                    expected_fulfillment_date: earliestIncoming,
                    customer_required_date: custDate,
                    customer_order: coId,
                    production_order: poId,
                    urgency: urgency,
                    decision_reason: reasonIncoming
                }, {
                    feasible: true,
                    reserved_quantity: reservedQty,
                    recommended_action: 'Await incoming procurement; no new order or transfer required.'
                });
            }
        }

        // ========================================
        // Steps 10-14: Check alternate warehouses
        // ========================================
        var altResult = router.listAlternateWarehouses(whId);
        var candidates = [];

        if (altResult.success) {
            for (var i = 0; i < altResult.warehouses.length; i++) {
                var altWh = altResult.warehouses[i];
                var altStock = this._getStock(matId, altWh.sys_id);
                // Step 11-12: Transferable = available only, NEVER safety stock
                var transferable = altStock.available;
                if (transferable <= 0) continue;

                var leadDays = this._getLeadTime(altWh.sys_id, whId);
                var arrivalDate = this._addDays(new GlideDateTime(), leadDays);
                var meetsDeadline = !custDate || arrivalDate.compareTo(new GlideDateTime(custDate)) <= 0;

                candidates.push({
                    warehouse: altWh,
                    transferable: transferable,
                    lead_time: leadDays,
                    arrival: arrivalDate,
                    meets_deadline: meetsDeadline
                });
            }
        }

        // Step 13-14: Evaluate candidates
        // Sort by: meets deadline first, then shortest lead time, then most stock
        candidates.sort(function (a, b) {
            if (a.meets_deadline && !b.meets_deadline) return -1;
            if (!a.meets_deadline && b.meets_deadline) return 1;
            if (a.lead_time !== b.lead_time) return a.lead_time - b.lead_time;
            return b.transferable - a.transferable;
        });

        // Check if one or more candidates can cover the shortage
        var totalTransferable = 0;
        for (var t = 0; t < candidates.length; t++) {
            totalTransferable += candidates[t].transferable;
        }

        if (totalTransferable >= shortage && candidates.length > 0) {
            var bestCandidate = candidates[0];
            var transferQty = Math.min(bestCandidate.transferable, shortage);
            var reason14 = matName + ': ' + qtyReq + ' units needed at ' +
                           assignedWh.location_name + '. Available locally: ' +
                           availQty + ', shortage: ' + shortage +
                           '. Transfer ' + transferQty + ' from ' +
                           bestCandidate.warehouse.location_name +
                           ' (available: ' + bestCandidate.transferable +
                           ', lead time: ' + bestCandidate.lead_time + 'd).';
            if (bestCandidate.meets_deadline) {
                reason14 += ' Meets customer deadline.';
            } else {
                reason14 += ' WARNING: May miss customer deadline.';
            }
            if (candidates.length > 1) {
                reason14 += ' Selected over ' + (candidates.length - 1) +
                            ' other warehouse(s) based on lead time and stock.';
            }

            return this._result({
                decision_type: 'INTER_WAREHOUSE_TRANSFER',
                material_product: matId,
                required_quantity: qtyReq,
                available_quantity: availQty,
                shortage_quantity: shortage,
                assigned_warehouse: whId,
                source_warehouse: bestCandidate.warehouse.sys_id,
                transfer_lead_time_days: bestCandidate.lead_time,
                expected_fulfillment_date: bestCandidate.arrival.getValue(),
                customer_required_date: custDate,
                customer_order: coId,
                production_order: poId,
                urgency: urgency,
                decision_reason: reason14
            }, {
                feasible: true,
                reserved_quantity: reservedQty,
                recommended_action: 'Initiate inter-warehouse transfer from ' +
                    bestCandidate.warehouse.location_name + '.'
            });
        }

        // ========================================
        // Steps 15-18: Evaluate procurement
        // ========================================
        if (supplierSysId) {
            // Note: no supplier_lead_time field exists yet on mat_master.
            // Use a default estimate. When the supplier price comparison
            // table is implemented, this will read actual lead times.
            var defaultSupplierLeadDays = 7;
            var procArrival = this._addDays(new GlideDateTime(), defaultSupplierLeadDays);
            var meetsProcDeadline = !custDate || procArrival.compareTo(new GlideDateTime(custDate)) <= 0;

            if (meetsProcDeadline) {
                var reason17 = matName + ': ' + qtyReq + ' units needed at ' +
                               assignedWh.location_name + '. Available locally: ' +
                               availQty + ', shortage: ' + shortage +
                               '. No alternate warehouse can supply. ' +
                               'Local supplier can deliver in ~' + defaultSupplierLeadDays +
                               ' days — within customer deadline. Recommend normal procurement.';
                return this._result({
                    decision_type: 'PROCUREMENT_LOCAL_SUPPLIER',
                    material_product: matId,
                    required_quantity: qtyReq,
                    available_quantity: availQty,
                    shortage_quantity: shortage,
                    assigned_warehouse: whId,
                    supplier: supplierSysId,
                    supplier_lead_time_days: defaultSupplierLeadDays,
                    expected_fulfillment_date: procArrival.getValue(),
                    customer_required_date: custDate,
                    customer_order: coId,
                    production_order: poId,
                    urgency: urgency,
                    decision_reason: reason17
                }, {
                    feasible: true,
                    reserved_quantity: reservedQty,
                    recommended_action: 'Raise a procurement order with the local supplier.'
                });
            }

            // Step 18: Check if alternate WH supplier route is faster
            // (supplier → alt WH → transfer → assigned WH)
            for (var p = 0; p < candidates.length; p++) {
                var altProcLead = defaultSupplierLeadDays;
                var altTransferLead = candidates[p].lead_time;
                var totalAltLead = altProcLead + altTransferLead;
                var altArrival = this._addDays(new GlideDateTime(), totalAltLead);
                if (!custDate || altArrival.compareTo(new GlideDateTime(custDate)) <= 0) {
                    var reason18 = matName + ': alternate route via ' +
                                   candidates[p].warehouse.location_name +
                                   '. Supplier → alt WH (' + altProcLead +
                                   'd) → transfer (' + altTransferLead +
                                   'd) = ' + totalAltLead + 'd total. Meets deadline.';
                    return this._result({
                        decision_type: 'PROCUREMENT_ALTERNATE_WAREHOUSE_SUPPLIER',
                        material_product: matId,
                        required_quantity: qtyReq,
                        available_quantity: availQty,
                        shortage_quantity: shortage,
                        assigned_warehouse: whId,
                        source_warehouse: candidates[p].warehouse.sys_id,
                        supplier: supplierSysId,
                        supplier_lead_time_days: altProcLead,
                        transfer_lead_time_days: altTransferLead,
                        expected_fulfillment_date: altArrival.getValue(),
                        customer_required_date: custDate,
                        customer_order: coId,
                        production_order: poId,
                        urgency: urgency,
                        decision_reason: reason18
                    }, {
                        feasible: true,
                        reserved_quantity: reservedQty,
                        recommended_action: 'Procure via alternate-warehouse supplier route through ' +
                            candidates[p].warehouse.location_name + '.'
                    });
                }
            }
        }

        // ========================================
        // Step 20: Unfulfillable
        // ========================================
        var reasonUnfulfillable = matName + ': ' + qtyReq + ' units needed at ' +
            assignedWh.location_name + '. Available locally: ' + availQty +
            ', safety stock: ' + safetyQty + ', shortage: ' + shortage +
            '. Alternate warehouses transferable: ' + totalTransferable +
            '. No supplier or procurement route can meet the deadline. ' +
            'Manual review required.';

        return this._result({
            decision_type: 'UNFULFILLABLE',
            material_product: matId,
            required_quantity: qtyReq,
            available_quantity: availQty,
            shortage_quantity: shortage,
            assigned_warehouse: whId,
            supplier: supplierSysId,
            customer_required_date: custDate,
            customer_order: coId,
            production_order: poId,
            urgency: urgency,
            decision_reason: reasonUnfulfillable
        }, {
            feasible: false,
            reserved_quantity: reservedQty,
            recommended_action: 'Escalate for manual review; no automated route meets the deadline.'
        });
    },

    /**
     * Build the standardized, NON-PERSISTED decision result object returned by
     * evaluateReadOnly(). `decision_data` is the exact object the persisting path
     * (evaluate -> _createDecision) consumes, guaranteeing behavioral equivalence.
     * This helper performs NO database operations.
     */
    _result: function (data, meta) {
        meta = meta || {};
        return {
            success: true,
            decision_type: data.decision_type,
            feasible: (meta.feasible === undefined ? true : meta.feasible),
            material: data.material_product || '',
            warehouse: data.assigned_warehouse || '',
            required_quantity: (data.required_quantity === undefined ? 0 : data.required_quantity),
            available_quantity: (data.available_quantity === undefined ? 0 : data.available_quantity),
            reserved_quantity: (meta.reserved_quantity === undefined ? 0 : meta.reserved_quantity),
            incoming_quantity: (data.incoming_quantity === undefined ? 0 : data.incoming_quantity),
            shortage_quantity: (data.shortage_quantity === undefined ? 0 : data.shortage_quantity),
            safety_stock_consumed: (data.safety_stock_consumed === undefined ? 0 : data.safety_stock_consumed),
            expected_fulfillment_date: data.expected_fulfillment_date || '',
            source_warehouse: data.source_warehouse || '',
            transfer_lead_time_days: (data.transfer_lead_time_days === undefined ? 0 : data.transfer_lead_time_days),
            supplier_lead_time_days: (data.supplier_lead_time_days === undefined ? 0 : data.supplier_lead_time_days),
            supplier: data.supplier || '',
            urgency: data.urgency || '',
            customer_required_date: data.customer_required_date || '',
            customer_order: data.customer_order || '',
            production_order: data.production_order || '',
            reason: data.decision_reason || '',
            recommended_action: meta.recommended_action || '',
            // Exact payload for the persisting path; keeps evaluate() equivalent.
            decision_data: data,
            // Directive only (e.g. safety-stock alert). evaluateReadOnly never acts on it.
            alert: meta.alert || null
        };
    },

    /** Aggregate stock at a warehouse. READ-ONLY. */
    _getStock: function (matId, whId) {
        var result = { available: 0, safety_stock: 0, reserved: 0, stock_sys_id: '' };
        var ga = new GlideAggregate(this.STOCK);
        ga.addQuery('material_product', matId);
        ga.addQuery('location', whId);
        ga.addQuery('active', true);
        ga.addQuery('status', 'available');
        ga.addAggregate('SUM', 'available_quantity');
        ga.addAggregate('SUM', 'safety_stock');
        ga.addAggregate('SUM', 'reserved_quantity');
        ga.query();
        if (ga.next()) {
            result.available = parseFloat(ga.getAggregate('SUM', 'available_quantity')) || 0;
            result.safety_stock = parseFloat(ga.getAggregate('SUM', 'safety_stock')) || 0;
            result.reserved = parseFloat(ga.getAggregate('SUM', 'reserved_quantity')) || 0;
        }
        // Get a specific stock record sys_id for alerts
        var sg = new GlideRecord(this.STOCK);
        sg.addQuery('material_product', matId);
        sg.addQuery('location', whId);
        sg.addQuery('active', true);
        sg.addQuery('status', 'available');
        sg.setLimit(1);
        sg.query();
        if (sg.next()) result.stock_sys_id = sg.getValue('sys_id');
        return result;
    },

    /** Directional lead time lookup. */
    _getLeadTime: function (srcId, dstId) {
        var lt = new GlideRecord(this.LEAD);
        lt.addQuery('source_warehouse', srcId);
        lt.addQuery('destination_warehouse', dstId);
        lt.addQuery('active', true);
        lt.setLimit(1);
        lt.query();
        if (lt.next()) return parseFloat(lt.getValue('lead_time_days')) || 0;
        return 0;
    },

    /** Calculate urgency from customer date. */
    _calcUrgency: function (custDate) {
        if (!custDate) return 'medium';
        var now = new GlideDateTime();
        var deadline = new GlideDateTime(custDate);
        var diffMs = GlideDateTime.subtract(now, deadline).getNumericValue();
        var diffDays = diffMs / (1000 * 60 * 60 * 24);
        if (diffDays <= 0) return 'critical';
        if (diffDays <= 2) return 'critical';
        if (diffDays <= 5) return 'high';
        if (diffDays <= 14) return 'medium';
        return 'low';
    },

    /** Add days to a GlideDateTime. */
    _addDays: function (gdt, days) {
        var result = new GlideDateTime(gdt);
        result.addDaysLocalTime(days);
        return result;
    },

    /** Create safety stock consumption alert (Step 9). PERSISTS — called only from evaluate(). */
    _createSafetyStockAlert: function (matId, whId, consumed, stockSysId) {
        if (!stockSysId) return;
        try {
            var alert = new GlideRecord(this.ALERT);
            alert.initialize();
            alert.setValue('alert_type', 'below_safety_stock');
            alert.setValue('severity', 'high');
            alert.setValue('material_product', matId);
            alert.setValue('inventory_stock', stockSysId);
            alert.setValue('alert_message',
                'Safety stock consumed for fulfillment: ' + consumed +
                ' units. Replenishment required.');
            alert.setValue('alert_date', new GlideDateTime().getValue());
            alert.setValue('status', 'new');
            alert.insert();
        } catch (e) {
            gs.warn('MaterialFulfillmentDecision: Could not create alert: ' + e.message);
        }
    },

    /** Persist the decision record. PERSISTS — called only from evaluate(). */
    _createDecision: function (data) {
        var dec = new GlideRecord(this.DEC);
        dec.initialize();
        for (var key in data) {
            if (data.hasOwnProperty(key) && data[key] !== '' && data[key] !== null && data[key] !== undefined) {
                dec.setValue(key, data[key].toString());
            }
        }
        dec.setValue('status', 'pending');
        dec.setValue('active', true);
        var decId = dec.insert();

        if (decId) {
            return {
                success: true,
                decision_type: data.decision_type,
                decision_sys_id: decId,
                reason: data.decision_reason,
                details: data
            };
        }
        return this._fail('Failed to create decision record');
    },

        /**
     * Query incoming procurement for a material (READ-ONLY).
     * Returns quantities ordered but not yet received from active procurement lines.
     * Does NOT create purchase orders or modify procurement data.
     */
    _getIncomingProcurement: function(materialSysId) {
        var result = { total_incoming: 0, lines: [], earliest_expected: null };
        var PO_LINE = "x_2056099_indust_0_po_line";
        var gr = new GlideRecord(PO_LINE);
        gr.addQuery("material_product", materialSysId);
        gr.addQuery("status", "IN", "pending,ordered,partially_received");
        gr.addQuery("remaining_quantity", ">", 0);
        gr.query();
        while (gr.next()) {
            var remaining = parseFloat(gr.getValue("remaining_quantity")) || 0;
            var expectedDate = gr.getValue("expected_delivery_date") || "";
            result.total_incoming += remaining;
            result.lines.push({
                po_line_sys_id: gr.getValue("sys_id"),
                procurement_order: gr.getDisplayValue("procurement_order"),
                remaining_quantity: remaining,
                expected_delivery_date: expectedDate,
                status: gr.getValue("status")
            });
            if (expectedDate && (!result.earliest_expected || expectedDate < result.earliest_expected)) {
                result.earliest_expected = expectedDate;
            }
        }
        return result;
    },

    _fail: function (reason) {
        return { success: false, error: reason };
    },

    type: 'MaterialFulfillmentDecision'
};
